// ExperimentServiceHandler is an implementation of the perfine.v1.ExperimentService service.
type ExperimentServiceHandler interface {
	// EXPERIMENT. Validate editable user configuration and compute authoritative core fingerprints.
	// Creates no experiment and never changes an already-started experiment.
	PrepareExperiment(context.Context, *connect.Request[v1.PrepareExperimentRequest]) (*connect.Response[v1.PrepareExperimentResponse], error)
	// READ. Cursor binds connection and filters; order by creation time and ID descending.
	ListExperiments(context.Context, *connect.Request[v1.ListExperimentsRequest]) (*connect.Response[v1.ListExperimentsResponse], error)
	// READ. Poll execution and cancellation status separately from performance verdict.
	GetExperiment(context.Context, *connect.Request[v1.GetExperimentRequest]) (*connect.Response[v1.GetExperimentResponse], error)
	// EXPERIMENT. Cloud execution only after eligibility and authority checks; client supplies a new UUID v7.
	StartExperiment(context.Context, *connect.Request[v1.StartExperimentRequest]) (*connect.Response[v1.StartExperimentResponse], error)
	// EXPERIMENT. Reuse completed steps only for the same immutable fingerprint; reject deleted IDs.
	ResumeExperiment(context.Context, *connect.Request[v1.ResumeExperimentRequest]) (*connect.Response[v1.ResumeExperimentResponse], error)
	// EXPERIMENT. Graceful stops new starts; immediate also stops active work. Preserve completed evidence.
	CancelExperiment(context.Context, *connect.Request[v1.CancelExperimentRequest]) (*connect.Response[v1.CancelExperimentResponse], error)
	// READ. Empty candidates is a valid completed outcome.
	ListCandidates(context.Context, *connect.Request[v1.ListCandidatesRequest]) (*connect.Response[v1.ListCandidatesResponse], error)
	// READ. Returns comparisons, correctness and approval requirements.
	GetCandidate(context.Context, *connect.Request[v1.GetCandidateRequest]) (*connect.Response[v1.GetCandidateResponse], error)
}

